mapper.select:
SELECT s.*, d.name as doctor_name, dept.name as dept_name
FROM schedule s
LEFT JOIN doctor d ON s.doctor_id = d.id
LEFT JOIN department dept ON d.dept_id = dept.id
WHERE s.deleted = 0 AND d.deleted = 0 AND dept.deleted = 0

    AND s.doctor_id = #{doctorId}


    AND d.dept_id = #{deptId}


    AND s.date >= #{startDate}


    AND s.date <= #{endDate}

ORDER BY s.date DESC, s.period ASC
